import{_ as d,o as e,c as o,a2 as a}from"./chunks/framework.DTdEDYjJ.js";const u=JSON.parse('{"title":"支持范围与验证状态","description":"","frontmatter":{},"headers":[],"relativePath":"guide/status.md","filePath":"guide/status.md"}'),r={name:"guide/status.md"};function i(n,t,h,s,l,p){return e(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="支持范围与验证状态" tabindex="-1">支持范围与验证状态 <a class="header-anchor" href="#支持范围与验证状态" aria-label="Permalink to &quot;支持范围与验证状态&quot;">​</a></h1><p>更新于 2026 年 11 月 17 日。公众可访问官网的交互预览和各端工程归档。私有主仓的 GitHub Releases 有 <strong>OpenBot v0.14.0 公司的试点 DMG</strong>。<strong>Bot Studio 1.0.33</strong> 已完成开发方本机安装验收，同版本安装包尚未上传。 <a href="/openbot/guide/platforms.html">平台与下载</a></p><p>网页用合成资料演示交互。桌面、云 Node、手机跨端和市场连接器分别记录验证范围。下表保留 0.10.9 至 0.14.0 的历史验收范围，1.0.33 的新能力与试点接入状态见<a href="/openbot/development/architecture-report.html">技术架构报告</a>。</p><h2 id="如何阅读状态" tabindex="-1">如何阅读状态 <a class="header-anchor" href="#如何阅读状态" aria-label="Permalink to &quot;如何阅读状态&quot;">​</a></h2><ul><li><strong>已实现</strong>：当前源码存在该路径；使用仍需满足配置、权限和运行环境要求。</li><li><strong>原型或隔离验收</strong>：指定版本和独立资料中验证过，不等同于日常安装包或所有客户端已交付。</li><li><strong>待验收</strong>：还没有完整的实际闭环，不能用相邻路径的成功替代。</li><li><strong>规划</strong>：尚不提供可依赖的产品入口。</li></ul><h2 id="能力矩阵" tabindex="-1">能力矩阵 <a class="header-anchor" href="#能力矩阵" aria-label="Permalink to &quot;能力矩阵&quot;">​</a></h2><table tabindex="0"><thead><tr><th>能力</th><th>当前范围</th><th>主要边界</th></tr></thead><tbody><tr><td>Mac 本地 Bot</td><td>已实现，Mac arm64</td><td>模型 API 或显式绑定的受支持本机智能体</td></tr><tr><td>模型与 Harness</td><td>已实现，默认 DSH，显式 Pi/legacy</td><td>模型可达不等于工具或浏览器任务已验证</td></tr><tr><td>浏览器 Computer Use</td><td>已实现，本机与自建 Node 的 Chromium</td><td>不是完整 Mac/Windows/Linux 桌面控制</td></tr><tr><td>主脑与执行 Bot</td><td>已实现，显式 API 主 Bot 工具与委派授权</td><td>模式切换不提高权限；不静默重派未知结果</td></tr><tr><td>空间与记忆</td><td>已实现，空间群聊/私聊与显式记忆范围</td><td>空间会话仍限本机 API 无工具文字</td></tr><tr><td>Linux Node</td><td>0.10.9 已部署，默认入口统一到主 Bot；正常重启保持状态</td><td>双屏与接管沿用历史验收；物理合盖/72小时仍未验收</td></tr><tr><td>GitHub 应用授权</td><td>本机真实 OAuth/加密保存已验收；云主 Bot 经实际 MCP 读取真实 GitHub 身份，按 Bot 授权与撤销拒绝已验证</td><td>本次云闭环限 <code>github.profile.read</code>；默认无 Bot 授权，桌面授权面板与自动 refresh 尚未交付</td></tr><tr><td>应用目录与网盘</td><td>提供应用入口、Logo、配置指引</td><td>卡片或网页登录不等于已实现连接器或授予 Bot 数据访问</td></tr><tr><td>外部 MCP / 微信 ClawBot</td><td>独立 Node 网关已有真实外部任务与微信结果记录</td><td>不是用微信登录 OpenBot；依赖独立凭据与入口权限</td></tr><tr><td>官方托管、跨账号 A2A</td><td>规划</td><td>无官方托管购买入口；A2A Adapter 尚未交付</td></tr></tbody></table><p>安装包与源码状态分别登记。已有0.10.9本地预览包的验收记录，不代表同版附件已公开上传，也不代表后续源码授权功能已包含在旧包中。</p><h2 id="云端应用授权的验证范围" tabindex="-1">云端应用授权的验证范围 <a class="header-anchor" href="#云端应用授权的验证范围" aria-label="Permalink to &quot;云端应用授权的验证范围&quot;">​</a></h2><p>实际 SDK stdio MCP 客户端已通过云端默认主 Bot，调用 <code>app_connections_list</code> 和 <code>app_connection_call</code>，由 <code>github.profile.read</code> 读回 GitHub 的真实身份资料。指定 Bot 获得连接与动作授权后才能使用，撤销后调用被拒绝；模型不取得应用 Token。</p><p>完成审计将应用调用归因到 Bot，并关联实际运行来源。本次成功后，云 Node 与微信接收器正常重启，连接、授权、审计与外部任务状态保持；MCP 重交同一逻辑请求返回既有任务结果，没有新增提供商调用。</p><p>GitHub 配额耗尽时的 <code>403</code> 会如实记录为失败，不自动换号重试。配额恢复后显式发起的新请求取得真实结果，原失败记录保留。任务的 <code>done</code> 状态与应用调用成功分别核验，不能以任务已终结替代工具结果。</p><p>本次结果不覆盖 Mac 安装包、桌面授权面板、自动 Token 续期、72 小时常驻、手机 App 公网 Hub 或新云双屏的验收。</p><h2 id="手机验证矩阵" tabindex="-1">手机验证矩阵 <a class="header-anchor" href="#手机验证矩阵" aria-label="Permalink to &quot;手机验证矩阵&quot;">​</a></h2><table tabindex="0"><thead><tr><th>路径</th><th>已有结果</th><th>尚未证明</th></tr></thead><tbody><tr><td>Android → Mac，USB</td><td>独立预览原型完成真实模型交办、结果读回、刷新与重启保留</td><td>日常 App 资料已同步</td></tr><tr><td>Android → Mac，LAN HTTPS</td><td>CA 信任、配对、授权目录、撤销与重新配对通过</td><td>LAN 真实模型任务未执行</td></tr><tr><td>微信 → 云端主脑 → 两个 Bot → 微信</td><td>真实汇总已由手机收件确认</td><td>Android App 公网 Hub 已接通</td></tr><tr><td>手机 App → 公网云 Hub</td><td>待验收</td><td>公网登录、配对、交办与结果读回完整闭环</td></tr><tr><td>新二维码入口</td><td>源码二维码可独立解码</td><td>最终新包的真机扫码与任务闭环</td></tr></tbody></table><p>同一 Wi-Fi 名称不保证设备互通；Mac 可以用网线接入同一局域网。手机需要可达的 HTTPS 入口、可信证书和独立设备授权，详见<a href="/openbot/deployment/network.html">网络连接</a>。</p><h2 id="验收与后续改进" tabindex="-1">验收与后续改进 <a class="header-anchor" href="#验收与后续改进" aria-label="Permalink to &quot;验收与后续改进&quot;">​</a></h2><p>取消、重启、断连和人工接管分别验证。任务被中断时保留准确状态，不自动重放可能产生副作用的操作；“模型说完成”和健康检查都不能代替实际结果。</p><p>下一步重点是桌面应用授权入口、手机 LAN 与公网真实任务、自动 Token 续期和首次配置收尾。贡献前请确认修改影响的是哪条路径，并在 PR 中说明已验证与未验证项。</p><p>详细源码记录见仓库 <code>docs/phone-link-status.md</code>、<code>docs/github-oauth-live-verification.json</code> 和 <code>docs/app-authorizations-verification.json</code>。继续阅读<a href="/openbot/guide/quickstart.html">快速开始</a>、<a href="/openbot/deployment/self-host.html">自建 Node</a>或<a href="/openbot/development/contributing.html">参与贡献</a>。</p>',20)])])}const b=d(r,[["render",i]]);export{u as __pageData,b as default};
